-- ============================================================================
-- V034: Commercial Billing & Subscription Lifecycle Architecture
-- ============================================================================
-- Strict Invariants:
-- 1. All domain IDs are UUIDv7 generated by application code.
-- 2. Server-authoritative checkout sessions prevent client tampering with prices or limits.
-- 3. Idempotent checkout session tracking per studio.
-- 4. Subscription source differentiation (PAID_PROVIDER vs MANUAL_ADMIN vs SYSTEM).
-- 5. Safe downgrade scheduling without data loss (downgrade_plan_id).
-- 6. Strict multi-tenant Row Level Security on billing_checkout_sessions.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. BILLING CHECKOUT SESSIONS
-- ----------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS billing_checkout_sessions (
    id uuid PRIMARY KEY,
    studio_id uuid NOT NULL REFERENCES designer_studios(id) ON DELETE CASCADE,
    plan_id uuid NOT NULL REFERENCES billing_plans(id),
    provider varchar(64) NOT NULL,
    provider_session_id varchar(128) NULL,
    idempotency_key varchar(128) NOT NULL,
    status varchar(32) NOT NULL,
    amount_minor bigint NOT NULL,
    currency varchar(3) NOT NULL DEFAULT 'INR',
    success_url varchar(1024) NOT NULL,
    cancel_url varchar(1024) NOT NULL,
    expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_checkout_studio_idempotency UNIQUE (studio_id, idempotency_key),
    CONSTRAINT chk_checkout_amount CHECK (amount_minor >= 0),
    CONSTRAINT chk_checkout_status CHECK (status IN ('PENDING', 'COMPLETED', 'EXPIRED', 'CANCELLED'))
);

CREATE INDEX IF NOT EXISTS idx_checkout_sessions_studio ON billing_checkout_sessions (studio_id, created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS idx_checkout_provider_session_id ON billing_checkout_sessions (provider, provider_session_id)
    WHERE provider_session_id IS NOT NULL;

-- ----------------------------------------------------------------------------
-- 2. SUBSCRIPTION METADATA & DOWNGRADE TRACKING
-- ----------------------------------------------------------------------------

ALTER TABLE studio_subscriptions ADD COLUMN IF NOT EXISTS source_type varchar(32) NOT NULL DEFAULT 'PAID_PROVIDER';
ALTER TABLE studio_subscriptions ADD COLUMN IF NOT EXISTS downgrade_plan_id uuid NULL REFERENCES billing_plans(id);
ALTER TABLE studio_subscriptions ADD COLUMN IF NOT EXISTS grace_period_end timestamptz NULL;

UPDATE studio_subscriptions SET source_type = 'MANUAL_ADMIN' WHERE provider = 'ADMIN_OVERRIDE';
UPDATE studio_subscriptions SET source_type = 'SYSTEM' WHERE provider = 'NONE';

ALTER TABLE studio_subscriptions DROP CONSTRAINT IF EXISTS chk_sub_source_type;
ALTER TABLE studio_subscriptions ADD CONSTRAINT chk_sub_source_type CHECK (source_type IN ('PAID_PROVIDER', 'MANUAL_ADMIN', 'SYSTEM'));

-- ----------------------------------------------------------------------------
-- 3. ROW LEVEL SECURITY (RLS) FOR CHECKOUT SESSIONS
-- ----------------------------------------------------------------------------

ALTER TABLE billing_checkout_sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE billing_checkout_sessions FORCE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS tenant_isolation_billing_checkout_sessions ON billing_checkout_sessions;
CREATE POLICY tenant_isolation_billing_checkout_sessions ON billing_checkout_sessions
    FOR ALL
    USING (
        studio_id = NULLIF(current_setting('app.current_studio_id', true), '')::uuid
        OR current_setting('app.is_admin', true) = 'true'
    );
